import {heroPortrait} from './portraits.js?v=13.0.0';
import * as M from './model.js?v=13.0.0';
import * as X from './expansion.js?v=13.0.0';
import {escapeHtml as esc} from './features.js?v=13.0.0';
const i=n=>`<i data-lucide="${n}"></i>`,n=v=>Math.floor(v||0).toLocaleString('en-US');
const btn=(label,action,attrs='',disabled=false)=>`<button class="btn btn-gold" data-x="${action}" ${attrs} ${disabled?'disabled':''}>${label}</button>`;
const timer=t=>`<span data-until="${t}">${Math.max(0,Math.ceil((t-Date.now())/1000))}s</span>`;
export class ExpansionUI{
 constructor(b){this.b=b;this.sig='';this.current='';document.getElementById('worlds-button').addEventListener('click',()=>this.frontiers().catch(e=>b.toast(e.message,true)));document.getElementById('season-button').addEventListener('click',()=>this.season());document.getElementById('return-village').addEventListener('click',()=>b.setRealm('home'));document.addEventListener('click',e=>{const el=e.target.closest('[data-x]');if(el&&!el.disabled)this.handle(el).catch(e=>b.toast(e.message,true));});}
 state(){const s=this.b.root();X.ensure(s);return s;}
 show(kind,title,body){this.current=kind;this.sig=this.signature();this.b.showModal('v3-'+kind,this.b.header('EMBERFALL · '+(kind==='heroes'?'HERO HALL':'THE EXPANDED KINGDOM'),title)+`<div class="modal-body expansion-body">${body}</div>`);for(const canvas of document.querySelectorAll('[data-portrait]'))this.b.portrait(canvas,canvas.dataset.portrait,Number(canvas.dataset.level)||1);}
 signature(){const s=this.state(),e=s.expansion;return JSON.stringify([s.heroes,e.equipment,e.equipmentWork,e.pets,e.loadouts,e.petAssignments,e.siege,e.siegeQueue,e.season,e.daily,s.buildings.map(b=>[b.type,b.level,!!b.finishAt])]);}
 tick(kind){if(kind==='v3-'+this.current&&['heroes','equipment','pets','workshop','season'].includes(this.current)&&this.sig!==this.signature())this[this.current]();}
 heroNav(){return `<div class="expansion-tabs">${btn(i('crown')+' Heroes','heroes')}${btn(i('shield')+' Equipment','equipment')}${btn(i('paw-print')+' Pets','pets')}${btn(i('axe')+' Siege','workshop')}${btn(i('swords')+' Training grounds','training')}</div>`;}
 heroes(){
  const s=this.state(),th=M.hallLevel(s);this.selectedHero=X.HOME_HEROES.includes(this.selectedHero)?this.selectedHero:'king';
  const k=this.selectedHero,d=M.HEROES[k],h=s.heroes[k],cap=M.heroMaxLevel(s,k),c=M.heroCost(h),locked=!M.heroUnlocked(s,k),level=Math.max(1,h.level),stats=X.heroStats(s,k,level),next=X.heroStats(s,k,level+1),requirements='TH '+d.unlock+' · Barracks '+(d.barracks||1)+' · Hero Hall';
  const roster=X.HOME_HEROES.map(id=>{const def=M.HEROES[id],hero=s.heroes[id],ready=M.heroUnlocked(s,id);return `<button class="hero-tile ${id===k?'selected':''} ${ready?'':'locked'}" data-x="hero-select" data-id="${id}" aria-pressed="${id===k}">${heroPortrait(id,'hero-tile-picture',Math.max(1,hero.level))}<strong>${def.name}</strong><small>${hero.finishAt?'Upgrading':hero.level?'Level '+hero.level:'TH '+def.unlock+' · Barracks '+(def.barracks||1)}</small></button>`;}).join('');
  const progress=h.finishAt?`<button class="hero-upgrade-progress" data-village="work" data-kind="hero" data-id="${k}"><span>Upgrade in progress · ${timer(h.finishAt)}</span><span>Tap to finish with gems</span></button>`:'';
  this.show('heroes','20 Heroes of Emberfall',this.heroNav()+`<p class="modal-intro">Town Hall ${th} / 15 · Barracks ${M.troopLevel(s)} · ${X.HOME_HEROES.filter(id=>s.heroes[id].level).length} / 20 heroes owned</p><div class="hero-browser"><div class="hero-gallery">${roster}</div><article class="hero-detail-card"><div class="hero-detail-heading">${heroPortrait(k,'hero-selected-picture',level)}<div><h3>${d.name}</h3><strong>${h.level?'Level '+h.level+' / '+cap:locked?'Locked':'Ready to unlock'}</strong><small>${requirements}</small></div></div><p>${d.desc}</p><div class="hero-stats hero-stats-labeled"><span><small>Hit points · HP</small><strong>${n(stats.hp)}</strong></span><span><small>Damage / hit</small><strong>${n(stats.damage)}</strong></span><span><small>Damage / second</small><strong>${n(stats.damage/d.rate)}</strong></span><span><small>Attack range</small><strong>${stats.range.toFixed(1)} tiles</strong></span></div><p class="hero-next">${h.level&&h.level<cap?'Next: '+n(next.hp)+' HP · '+n(next.damage)+' damage / hit':!h.level?'Level 1 preview · Unlock to deploy':h.level>=50?'Maximum hero level reached':'Upgrade Town Hall or Barracks to raise the cap.'}</p>${progress}${h.recoverAt>Date.now()?'<p>Recovering · '+timer(h.recoverAt)+'</p>':''}<div class="hero-detail-actions">${h.finishAt?btn(i('gem')+' '+M.skipCost(h.finishAt)+' · Finish now','hero-skip',`data-id="${k}"`):btn(locked?requirements:i('fuel')+' '+n(c.dark)+' · '+(h.level?'Upgrade':'Unlock'),'hero-upgrade',`data-id="${k}"`,locked||h.level>=cap||h.recoverAt>Date.now()||s.dark<c.dark)}<button class="btn" data-village="detail" data-kind="hero" data-type="${k}" data-level="${level}">${i('scan')} Inspect 3D</button></div><small class="loadout-note">${s.expansion.loadouts[k].map(id=>X.EQUIPMENT[id].name).join(' + ')}</small></article></div><p class="guide-foot">Training grounds lend all 20 heroes for practice. Upgrades and real ownership require the shown Town Hall, Barracks and Hero Hall levels.</p>`);
 }
 equipment(){const s=this.state(),e=s.expansion;this.show('equipment','Hero equipment',this.heroNav()+`<p class="wallet-total">${i('gem')} ${n(e.ore)} <span>ore</span></p>${e.equipmentWork?`<p>Upgrading ${X.EQUIPMENT[e.equipmentWork.id].name} · ${timer(e.equipmentWork.finishAt)}</p>`:''}<div class="loadout-list">${X.HOME_HEROES.filter(k=>s.heroes[k].level).map(k=>`<div class="loadout-row"><strong>${M.HEROES[k].name}</strong>${[0,1].map(slot=>`<label>Slot ${slot+1}<select id="gear-${k}-${slot}">${Object.keys(X.EQUIPMENT).map(id=>`<option value="${id}" ${e.loadouts[k][slot]===id?'selected':''}>${X.EQUIPMENT[id].name} · Lv ${e.equipment[id]}</option>`).join('')}</select>${btn('Equip','equip',`data-hero="${k}" data-slot="${slot}"`)}</label>`).join('')}</div>`).join('')||'<p>Unlock a hero to equip two different items.</p>'}</div><div class="card-grid">${Object.entries(X.EQUIPMENT).map(([id,d])=>`<article class="shop-card"><span class="card-icon">${i(d.icon)}</span><h3>${d.name}</h3><strong>Level ${e.equipment[id]} / 18</strong><p>${d.desc} Each level improves its effect.</p>${btn(n(X.equipmentCost(e.equipment[id]))+' ore · Upgrade','equipment-upgrade',`data-id="${id}"`,!!e.equipmentWork||e.equipment[id]>=18)}</article>`).join('')}</div>`);}
 pets(){const s=this.state(),e=s.expansion;this.show('pets','Hero companions',this.heroNav()+`<p class="modal-intro">One companion per hero. A pet joins its hero on deployment and fights or heals automatically. A pet can be assigned to one hero at a time.</p><div class="card-grid">${Object.entries(X.PETS).map(([id,d])=>{const p=e.pets[id];return `<article class="shop-card"><canvas class="pet-portrait" width="180" height="160" data-portrait="pet:${id}"></canvas><h3>${d.name}</h3><strong>${p.level?'Level '+p.level+' / 10':'Unlocks at TH '+d.unlock}</strong><p>${d.desc}</p>${p.finishAt?`<p>Training · ${timer(p.finishAt)}</p>`:btn(i('fuel')+' '+100*(p.level+1)+' · '+(p.level?'Upgrade':'Unlock'),'pet-upgrade',`data-id="${id}"`,M.hallLevel(s)<d.unlock||p.level>=10||Object.values(e.pets).some(p=>p.finishAt))}</article>`;}).join('')}</div><div class="loadout-list">${X.HOME_HEROES.filter(k=>s.heroes[k].level).map(k=>`<div class="loadout-row"><strong>${M.HEROES[k].name}</strong><select id="pet-${k}" aria-label="Companion for ${M.HEROES[k].name}"><option value="none">No companion</option>${Object.keys(X.PETS).filter(p=>e.pets[p].level&&!e.pets[p].finishAt).map(id=>`<option value="${id}" ${e.petAssignments[k]===id?'selected':''}>${X.PETS[id].name}</option>`).join('')}</select>${btn('Assign','pet-assign',`data-hero="${k}"`)}</div>`).join('')}</div>`);}
 workshop(){const s=this.state(),e=s.expansion;this.show('workshop','Siege workshop',this.heroNav()+`<p class="modal-intro">Store three siege machines. Deploy one per battle. Rams and airships release reinforcements when destroyed.</p><div class="card-grid">${Object.entries(X.SIEGE).map(([id,d])=>`<article class="shop-card"><canvas class="pet-portrait" width="180" height="160" data-portrait="siege:${id}"></canvas><h3>${d.name}</h3><strong>${e.siege[id]} ready · TH ${d.unlock}</strong><p>${d.desc}</p>${btn(i('droplets')+' '+d.cost+' · Build','siege-build',`data-id="${id}"`,M.hallLevel(s)<d.unlock)}</article>`).join('')}</div><p>${e.siegeQueue.map(q=>X.SIEGE[q.type].name+' · '+timer(q.finishAt)).join(' / ')||'Workshop is ready.'}</p>`);}
 season(){const s=this.state(),e=s.expansion;this.show('season','Season journey · '+e.season.id,`<p class="wallet-total">${i('trophy')} ${e.season.points} <span>season points</span></p><p class="modal-intro">Earn 20 points per battle star. Complete daily challenges for more. The free reward track resets on the first day of each UTC month.</p><h3>Daily challenges · ${e.daily.id}</h3><div class="quest-list">${X.SEASON_TASKS.map(q=>{const value=(s.stats[q.stat]||0)-(e.daily.baseline[q.stat]||0),claimed=e.daily.claimed.includes(q.id);return `<div class="quest-row"><div><strong>${q.title}</strong><small>${Math.min(q.goal,value)}/${q.goal} · ${q.xp} points + 30 ore</small></div>${btn(claimed?'Claimed':'Claim','daily-claim',`data-id="${q.id}"`,claimed||value<q.goal)}</div>`;}).join('')}</div><h3>Free season pass</h3><div class="season-track">${Array.from({length:20},(_,i)=>i+1).map(t=>`<article class="season-tier ${e.season.claimed.includes(t)?'claimed':''}"><strong>Tier ${t}</strong><small>${t*100} points</small><p>${50+t*5} ore<br>100 capital gold</p>${btn(e.season.claimed.includes(t)?'Claimed':'Claim','season-claim',`data-tier="${t}"`,e.season.points<t*100||e.season.claimed.includes(t))}</article>`).join('')}</div>`);}
 async frontiers(tab='worlds'){
  const s=this.state(),online=this.b.api.online;let data=null;if(online){data=await this.b.api.request('/frontiers');this.data=data;}const clan=data?.clan,c=data?.world;
  const tabs=`<div class="expansion-tabs">${[['worlds','Worlds'],['war','Clan Wars'],['league','Clan League'],['capital','Clan Capital'],['medals','Raid shop']].map(([id,label])=>btn(label,'frontiers',`data-tab="${id}"`)).join('')}</div>`;
  let body='';if(tab==='worlds'){const v=s.expansion.builder;body=`<div class="card-grid"><article class="shop-card"><span class="card-icon">${i('moon')}</span><h3>Builder Base</h3><p>Build a second village with its own resources, army, upgrades and Battle Machine.</p><strong>Builder Hall ${M.hallLevel(v)} · ${n(v.gold)} gold</strong>${btn('Visit Builder Base','visit-builder')}</article><article class="shop-card"><span class="card-icon">${i('castle')}</span><h3>Clan Capital</h3><p>Develop a shared capital. Raid three enemy districts with persistent damage.</p>${btn('Visit Capital','visit-capital','',!clan)}</article><article class="shop-card"><span class="card-icon">${i('swords')}</span><h3>Clan Wars</h3><p>Real opposing clans, equal rosters up to 5v5, preparation time and shared war stars.</p>${btn('War map','frontiers','data-tab="war"',!clan)}</article><article class="shop-card"><span class="card-icon">${i('trophy')}</span><h3>Clan League</h3><p>Seven rounds against AI strongholds. Each clanmate contributes one attack per round.</p>${btn('League board','frontiers','data-tab="league"',!clan)}</article></div><div class="machine-card">${heroPortrait('machine','',v.heroes.machine.level)}<canvas class="hero-model-preview" width="180" height="210" data-portrait="machine" data-level="${v.heroes.machine.level}"></canvas><div><h3>Battle Machine · Level ${v.heroes.machine.level}</h3><p>Builder Hall ${M.hallLevel(v)} · Hero cap ${M.hallLevel(v)*5}</p><p class="machine-stats">HP ${n(X.heroStats(v,'machine',v.heroes.machine.level).hp)} · Damage / hit ${n(X.heroStats(v,'machine',v.heroes.machine.level).damage)} · DPS ${n(X.heroStats(v,'machine',v.heroes.machine.level).damage/M.HEROES.machine.rate)}</p>${v.heroes.machine.finishAt?timer(v.heroes.machine.finishAt):btn(n(500*(v.heroes.machine.level+1))+' builder elixir · Upgrade','machine-upgrade')}</div></div>`;}
  else if(tab==='medals'){body=`<p class="wallet-total">${i('medal')} ${n(s.expansion.medals)} <span>raid medals</span></p><div class="panel-actions">${btn('200 ore · 20 medals','medal-exchange','data-id="ore"')}${btn('500 capital gold · 15 medals','medal-exchange','data-id="capitalGold"')}</div>`;}
  else if(!clan)body='<p class="modal-intro">Join or create a clan from Clans & Rivals to begin.</p>';
  else if(tab==='war'){
   body=`<p class="modal-intro">${esc(clan.name)} · The leader declares a war. Highest-glory members fill equal rosters (1–5 per side). One minute of preparation, then 24 hours to attack. Each target may be attacked once by each player, with up to two attacks per player.</p>${data.wars.filter(w=>w.status!=='ended').map(w=>{const side=w.clans.a===clan.id?'a':'b',other=side==='a'?'b':'a',score=k=>Object.values(w.best[k]).reduce((n,v)=>n+v.stars,0);return `<article class="war-board"><h3>${esc(w.names.a)} <span>${score('a')} ★ — ${score('b')} ★</span> ${esc(w.names.b)}</h3><p>${Date.now()<w.readyAt?'Preparing · '+timer(w.readyAt):'Time remaining · '+timer(w.endsAt)}</p><div class="enemy-list">${w.rosters[other].map(p=>`<div class="enemy-row"><div class="enemy-data"><strong>${esc(p.name)}</strong><small>TH ${p.hall} · Best ${w.best[side][p.id]?.stars||0} ★ / ${w.best[side][p.id]?.percent||0}%</small></div>${btn('Attack','war-attack',`data-war="${w.id}" data-id="${p.id}"`,Date.now()<w.readyAt||Date.now()>=w.endsAt||!w.rosters[side].some(p=>p.id===this.b.api.user.id)||(w.used[this.b.api.user.id]||[]).includes(p.id)||(w.used[this.b.api.user.id]?.length||0)>=Math.min(2,w.rosters[other].length))}</div>`).join('')}</div></article>`;}).join('')}`;
   body+=`<h3>Declare war</h3><div class="enemy-list">${data.clans.filter(v=>v.id!==clan.id).map(v=>`<div class="enemy-row"><strong>${esc(v.name)}</strong>${btn('Declare war','war-start',`data-id="${v.id}"`,clan.owner_id!==this.b.api.user.id||data.wars.some(w=>w.status!=='ended'))}</div>`).join('')||'<p>Another clan needs to be created on this server.</p>'}</div><h3>Finished wars</h3>${data.wars.filter(w=>w.status==='ended').map(w=>`<div class="enemy-row"><div class="enemy-data"><strong>${esc(w.names.a)} vs ${esc(w.names.b)}</strong><small>${w.winner==='draw'?'Draw':esc(w.names[w.winner])+' won'}</small></div>${btn(w.claimed.includes(this.b.api.user.id)?'Claimed':'Claim reward','war-claim',`data-war="${w.id}"`,w.claimed.includes(this.b.api.user.id))}</div>`).join('')}`;
  }else if(tab==='capital'){const r=c.raid;body=`<p class="modal-intro">${esc(clan.name)} · Everyone can donate and raid. The clan leader builds and moves the shared Capital. Damage carries over between clan attacks.</p><div class="capital-balances"><strong>Your capital gold: ${n(s.expansion.capitalGold)}</strong><strong>Clan treasury: ${n(c.village.gold)}</strong></div><div class="panel-actions">${btn('Donate 250','capital-donate','data-amount="250"',s.expansion.capitalGold<250)}${btn('Donate 1,000','capital-donate','data-amount="1000"',s.expansion.capitalGold<1000)}${btn('Open 3D Capital','visit-capital')}</div><article class="war-board"><h3>${['Capital Peak','Dragon Cliffs','Forge Valley'][r.district]}</h3><p>${r.district+1}/3 districts · ${r.conquered} capitals conquered · ${r.uses[this.b.api.user.id]||0}/5 attacks used this raid week</p>${btn(r.active?'Clanmate is attacking':'Attack district','capital-raid','',!!r.active||(r.uses[this.b.api.user.id]||0)>=5)}</article><p class="guide-foot">Destroy buildings for capital gold and raid medals. Five attacks renew each seven-day UTC raid cycle. Selecting an attack spends one attempt.</p>`;}
  else if(tab==='league'){const l=c.league;body=`<p class="modal-intro">A seven-round PvE clan league against progressively stronger AI bases. Each roster member gets one attack per round. Rewards are earned together.</p>${!l?btn('Enter monthly league','league-start','',clan.owner_id!==this.b.api.user.id):`<article class="war-board"><h3>${l.season} · ${l.ended?'League complete':'Round '+(l.round+1)+' / 7'}</h3><p>${l.roster.map(p=>esc(p.name)+(l.used[p.id]?' ✓':'')).join(' · ')}</p>${!l.ended?`<div class="panel-actions">${btn('Attack AI stronghold','league-attack','',!!l.used[this.b.api.user.id]||!l.roster.some(p=>p.id===this.b.api.user.id))}${btn(l.round===6?'Finish league':'Next round','league-next','',clan.owner_id!==this.b.api.user.id||l.active.length>0)}</div><p>The leader can advance after everyone attacks, or after 15 minutes.</p>`:btn(l.claimed.includes(this.b.api.user.id)?'Claimed':'Claim league medals','league-claim','',l.claimed.includes(this.b.api.user.id))}<div class="league-results">${l.scores.map(r=>`<span>Round ${r.round}<strong>${r.stars} / ${r.max} ★</strong></span>`).join('')}</div></article>${l.ended&&l.season!==new Date().toISOString().slice(0,7)?btn('Enter new season','league-start','',clan.owner_id!==this.b.api.user.id):''}`}`;}
  this.tab=tab;this.show('frontiers',tab==='worlds'?'Explore your kingdom':tab==='war'?'Clan Wars':tab==='league'?'Clan League':tab==='capital'?'Clan Capital':'Raid medal shop',tabs+(!online?'<p class="shop-status">Run the included server for shared clans, wars, leagues and Capital raids. Builder Base and hero training also work offline.</p>':'')+body);
 }
 siegeCards(b,selected){return Object.entries(X.SIEGE).filter(([k])=>b.siegeStock?.[k]).map(([k,d])=>`<button class="deploy-card ${selected===k?'selected':''}" data-x="select-siege" data-id="${k}" ${b.siegeDeployed?'disabled':''}><b>${b.siegeStock[k]}</b>${i(d.icon)}<span>${d.name}</span></button>`).join('');}
 async handle(el){const a=el.dataset.x;el.disabled=true;try{
  if(a==='hero-select'){this.selectedHero=el.dataset.id;this.heroes();return;}
  if(['heroes','equipment','pets','workshop','season'].includes(a)){this[a]();return;}
  if(a==='frontiers'){await this.frontiers(el.dataset.tab||'worlds');return;}
  if(a==='visit-builder'){this.b.setRealm('builder');return;}
  if(a==='visit-capital'){const d=await this.b.api.request('/frontiers');if(!d.world)throw Error('Join a clan first.');this.b.setCapital(d.world.village,d.clan.owner_id===this.b.api.user.id);return;}
  if(a==='select-siege'){this.b.selectSiege(el.dataset.id);return;}
  const modes={training:{mode:'training'},'war-attack':{mode:'war',warId:el.dataset.war,target:el.dataset.id},'capital-raid':{mode:'capital'},'league-attack':{mode:'league'}};if(modes[a]){await this.b.startMode(modes[a]);return;}
  const action={'hero-upgrade':{type:'hero-upgrade',hero:el.dataset.id},'hero-skip':{type:'skip',kind:'hero',id:el.dataset.id},equip:{type:'equipment-equip',hero:el.dataset.hero,slot:Number(el.dataset.slot),item:document.getElementById(`gear-${el.dataset.hero}-${el.dataset.slot}`)?.value},'equipment-upgrade':{type:a,item:el.dataset.id},'pet-upgrade':{type:a,pet:el.dataset.id},'pet-assign':{type:a,hero:el.dataset.hero,pet:document.getElementById('pet-'+el.dataset.hero)?.value},'siege-build':{type:a,siege:el.dataset.id},'daily-claim':{type:a,id:el.dataset.id},'season-claim':{type:a,tier:Number(el.dataset.tier)},'machine-upgrade':{type:a,realm:'builder'},'war-start':{type:a,opponent:el.dataset.id},'war-claim':{type:a,warId:el.dataset.war},'capital-donate':{type:a,amount:Number(el.dataset.amount)},'league-start':{type:a},'league-next':{type:a},'league-claim':{type:a},'medal-exchange':{type:a,item:el.dataset.id}}[a];
  if(action){await this.b.mutate({realm:'home',...action});this.b.toast('Done.');if(this.current==='frontiers')await this.frontiers(this.tab);else this[this.current]();}
 }finally{if(el.isConnected)el.disabled=false;}}
}
